package android.os;import java.util.*;public class Bundle {public Map<String,Object> values=new HashMap<>();public void putString(String k,String v){values.put(k,v);}public String getString(String k){return (String)values.get(k);}public void putInt(String k,int v){values.put(k,v);}public int getInt(String k){Object v=values.get(k);return v==null?0:(Integer)v;}public void putLong(String k,long v){values.put(k,v);}public long getLong(String k){Object v=values.get(k);return v==null?0:((Number)v).longValue();}public void putBoolean(String k,boolean v){values.put(k,v);}public boolean getBoolean(String k){Object v=values.get(k);return v!=null&&(Boolean)v;}}